// Ensure we handle incoming items regardless of whether the output is a raw string or an object
const cleanedItems = [];

// Simple regex helpers
const emailRegex = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const phoneDigitsRegex = /\D/g; // to strip non-numeric characters

for (const item of $input.all()) {
  let rawData = item.json;

  // 1. If AI output is wrapped in a string (e.g., raw text or inside a property like 'text', 'output', etc.)
  if (typeof rawData === 'string') {
    try {
      // Remove possible markdown code block fences (```json ... ```)
      const sanitized = rawData.replace(/```json/gi, '').replace(/```/g, '').trim();
      rawData = JSON.parse(sanitized);
    } catch (e) {
      cleanedItems.push({
        json: {
          error: "Failed to parse JSON string",
          raw: rawData
        }
      });
      continue;
    }
  } else if (rawData.text && typeof rawData.text === 'string') {
    // If output is nested under a 'text' property from an LLM node
    try {
      const sanitized = rawData.text.replace(/```json/gi, '').replace(/```/g, '').trim();
      rawData = JSON.parse(sanitized);
    } catch (e) {
      // Keep rawData as is if not a JSON string
    }
  }

  // If the parsed result is an array of items, normalize to loop through them
  const records = Array.isArray(rawData) ? rawData : [rawData];

  for (const record of records) {
    // Extract & trim fields safely
    const studentId = (record.Student_ID || record.student_id || '').toString().trim();
    const name = (record.Name || record.name || '').toString().trim();
    const rawEmail = (record.Email || record.email || '').toString().trim().toLowerCase();
    const rawPhone = (record.Phone || record.phone || '').toString().trim();
    const course = (record.Course || record.course || '').toString().trim();
    const feePaid = Boolean(record.Fee_Paid ?? record.fee_paid);
    const city = (record.City || record.city || '').toString().trim();
    const enrolledDate = (record.Enrolled_Date || record.enrolled_date || '').toString().trim();

    // 2. Validate Email
    const isEmailValid = emailRegex.test(rawEmail);
    const cleanEmail = isEmailValid ? rawEmail : null;

    // 3. Clean & Validate Phone (strips spaces, dashes, symbols)
    const digitsOnlyPhone = rawPhone.replace(phoneDigitsRegex, '');
    const isPhoneValid = digitsOnlyPhone.length >= 10 && digitsOnlyPhone.length <= 15;

    // 4. Format/Capitalize strings
    const formattedCourse = course
      ? course.charAt(0).toUpperCase() + course.slice(1).toLowerCase()
      : '';
    const formattedCity = city
      ? city.charAt(0).toUpperCase() + city.slice(1).toLowerCase()
      : '';

    // 5. Structure clean object
    cleanedItems.push({
      json: {
        student_id: studentId,
        name: name,
        email: cleanEmail,
        is_email_valid: isEmailValid,
        phone: digitsOnlyPhone || null,
        is_phone_valid: isPhoneValid,
        course: formattedCourse,
        fee_paid: feePaid,
        city: formattedCity,
        enrolled_date: enrolledDate || null,
        has_errors: !isEmailValid || !isPhoneValid
      }
    });
  }
}

return cleanedItems;

item.json.name = item.json.name ? item.json.name.trim() : '';
item.json.email = item.json.email ? item.json.email.trim().toLowerCase() : null;

return item;
